def admit(active, waiting, budget, slots):
    # Pre-check: if any waiting reservation exceeds the total budget, raise ValueError
    for value in waiting:
        if value > budget:
            raise ValueError(f"Reservation {value} exceeds total budget {budget}")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    for value in waiting:
        if value <= remaining_budget and remaining_slots > 0:
            admitted.append(value)
            remaining_budget -= value
            remaining_slots -= 1
        else:
            break

    remaining = waiting[len(admitted):]
    return admitted, remaining

